#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

# Run from the repo root so `gh secret set` targets michaelrubi/atcStudio.
cd "$(dirname "$0")/.."
# Signing secrets go only to GitHub, never to a file in the repo.
ENV_FILE="/dev/null"

TOTAL_STAGES=7

banner "ATC Studio: Developer ID signing + notarization for GitHub releases"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Check GitHub access"
if ! gh auth status >/dev/null 2>&1; then
  warn "gh is not logged in. Run: gh auth login   then run this wizard again."
  exit 1
fi
say "Secrets will be saved to this GitHub repo:"
note "  $(gh repo view --json nameWithOwner --jq .nameWithOwner)"
say "You need the Account Holder role on your Apple Developer team"
say "to create a Developer ID certificate."
pause "Press Enter to continue"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Apple Team ID"
open_url "https://developer.apple.com/account#MembershipDetailsCard"
step "Sign in. Find 'Membership details'."
step "Copy the Team ID (10 letters and numbers, for example A1B2C3D4E5)."
ask APPLE_TEAM_ID "Paste the Team ID:"
set_secret APPLE_TEAM_ID "$APPLE_TEAM_ID"
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Create the Developer ID Application certificate"
say "Do this in Xcode on this Mac:"
step "Xcode → Settings… → Accounts. Select your Apple ID, then your team."
step "Click 'Manage Certificates…'."
step "Click + (bottom left) → 'Developer ID Application'. Click Done."
note "Skip this if a Developer ID Application certificate is already listed."
pause "Press Enter when the certificate is created"
say "Developer ID certificates found on this Mac:"
if ! security find-identity -v -p codesigning | grep "Developer ID Application"; then
  warn "None found yet. Check Xcode again before you continue."
  pause "Press Enter to try the next stage anyway"
fi
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Export the certificate as a .p12 file"
say "Do this in Keychain Access on this Mac:"
step "Open Keychain Access. Select 'login' (left), then the 'My Certificates' tab."
step "Right-click 'Developer ID Application: <your name> (<Team ID>)' → Export…"
step "Format: Personal Information Exchange (.p12). Save it to your Desktop as"
note "      atc_developer_id.p12"
step "Make up a password for the file when asked. You will type it here next."
open -a "Keychain Access" >/dev/null 2>&1 || true
pause "Press Enter when the file is saved"
ask P12_PATH "Path to the .p12 file [$HOME/Desktop/atc_developer_id.p12]:"
P12_PATH="${P12_PATH:-$HOME/Desktop/atc_developer_id.p12}"
P12_PATH="${P12_PATH/#\~/$HOME}"
while [[ ! -f "$P12_PATH" ]]; do
  warn "No file at $P12_PATH"
  ask P12_PATH "Path to the .p12 file:"
  P12_PATH="${P12_PATH/#\~/$HOME}"
done
ask_secret DEVELOPER_ID_P12_PASSWORD "Type the .p12 password you just made (hidden):"
if openssl pkcs12 -in "$P12_PATH" -nokeys -passin "pass:$DEVELOPER_ID_P12_PASSWORD" >/dev/null 2>&1; then
  say "Password opens the file. Good."
else
  note "Could not check the password with openssl (this can be normal). Continuing."
fi
set_secret DEVELOPER_ID_P12_BASE64 "$(base64 -i "$P12_PATH")"
set_secret DEVELOPER_ID_P12_PASSWORD "$DEVELOPER_ID_P12_PASSWORD"
if confirm "Delete $P12_PATH now? (The certificate stays in your keychain.)"; then
  rm -f "$P12_PATH"
  say "Deleted."
fi
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Temporary keychain password for the build machine"
say "GitHub's Mac makes a throwaway keychain to hold the certificate."
say "This makes a random password for it. Nothing to do."
set_secret KEYCHAIN_PASSWORD "$(openssl rand -base64 30)"
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "App Store Connect API key (for notarization)"
open_url "https://appstoreconnect.apple.com/access/integrations/api"
step "Open the 'Team Keys' tab. (First time: click 'Request Access' and accept.)"
step "Click + (or 'Generate API Key'). Name: ATC Studio Notarization. Access: Developer."
step "Click Generate. Then click 'Download' on the new key."
warn "Apple lets you download the .p8 file only once. Keep it until this stage is done."
step "Copy the 'Issuer ID' shown above the table."
step "Copy the new key's 'Key ID' from the table."
ask NOTARY_ISSUER_ID "Paste the Issuer ID:"
ask NOTARY_KEY_ID "Paste the Key ID:"
P8_DEFAULT="$HOME/Downloads/AuthKey_${NOTARY_KEY_ID}.p8"
ask P8_PATH "Path to the .p8 file [$P8_DEFAULT]:"
P8_PATH="${P8_PATH:-$P8_DEFAULT}"
P8_PATH="${P8_PATH/#\~/$HOME}"
while [[ ! -f "$P8_PATH" ]]; do
  warn "No file at $P8_PATH"
  ask P8_PATH "Path to the .p8 file:"
  P8_PATH="${P8_PATH/#\~/$HOME}"
done
set_secret NOTARY_ISSUER_ID "$NOTARY_ISSUER_ID"
set_secret NOTARY_KEY_ID "$NOTARY_KEY_ID"
set_secret NOTARY_KEY_P8_BASE64 "$(base64 -i "$P8_PATH")"
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Test the notarization key"
say "Asking Apple's notary service to list past submissions with this key…"
if xcrun notarytool history --key "$P8_PATH" --key-id "$NOTARY_KEY_ID" --issuer "$NOTARY_ISSUER_ID" >/dev/null 2>&1; then
  say "Apple accepted the key. Notarization will work."
else
  warn "Apple did not accept the key. Check the Key ID, Issuer ID, and that Access is Developer."
  SKIPPED+=("Re-check the App Store Connect API key (notarytool history failed)")
fi
note "Keep the .p8 somewhere safe (a password manager), or delete it: it is in GitHub now."
pause

finish
say "Secret names for the release workflow:"
note "  APPLE_TEAM_ID  DEVELOPER_ID_P12_BASE64  DEVELOPER_ID_P12_PASSWORD  KEYCHAIN_PASSWORD"
note "  NOTARY_KEY_ID  NOTARY_ISSUER_ID  NOTARY_KEY_P8_BASE64"
printf '\n'
}

run_wizard "$@"; exit
